export type ParsedAddNftInstruction<
  TProgram extends string = typeof MALLOW_GUMBALL_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Gumball Machine account. */
    gumballMachine: TAccountMetas[0];
    /** Seller history account. */
    sellerHistory: TAccountMetas[1];
    authorityPda: TAccountMetas[2];
    /** Seller of the nft */
    seller: TAccountMetas[3];
    mint: TAccountMetas[4];
    tokenAccount: TAccountMetas[5];
    metadata: TAccountMetas[6];
    edition: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    tokenMetadataProgram: TAccountMetas[9];
    systemProgram: TAccountMetas[10];
    /** OPTIONAL PNFT ACCOUNTS */
    sellerTokenRecord?: TAccountMetas[11] | undefined;
    authRules?: TAccountMetas[12] | undefined;
    instructions?: TAccountMetas[13] | undefined;
    authRulesProgram?: TAccountMetas[14] | undefined;
  };
  data: AddNftInstructionData;
};

export function parseAddNftInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedAddNftInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 15) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 15,
      }
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === MALLOW_GUMBALL_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      gumballMachine: getNextAccount(),
      sellerHistory: getNextAccount(),
      authorityPda: getNextAccount(),
      seller: getNextAccount(),
      mint: getNextAccount(),
      tokenAccount: getNextAccount(),
      metadata: getNextAccount(),
      edition: getNextAccount(),
      tokenProgram: getNextAccount(),
      tokenMetadataProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      sellerTokenRecord: getNextOptionalAccount(),
      authRules: getNextOptionalAccount(),
      instructions: getNextOptionalAccount(),
      authRulesProgram: getNextOptionalAccount(),
    },
    data: getAddNftInstructionDataDecoder().decode(instruction.data),
  };
}
